code='''def transform(grid):
    grid = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    sep_rows = [r for r, row in enumerate(grid) if all(v == 8 for v in row)]
    sep_cols = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]
    row_runs, col_runs = [], []
    start = 0
    for r in sep_rows:
        if start < r:
            row_runs.append((start, r))
        start = r + 1
    if start < h:
        row_runs.append((start, h))
    start = 0
    for c in sep_cols:
        if start < c:
            col_runs.append((start, c))
        start = c + 1
    if start < w:
        col_runs.append((start, w))

    markers = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color not in (0, 8):
                tr = next((i for i, (a, b) in enumerate(row_runs) if a <= r < b), None)
                tc = next((i for i, (a, b) in enumerate(col_runs) if a <= c < b), None)
                if tr is not None and tc is not None:
                    markers.setdefault(color, []).append((tr, tc))

    painted = {}
    for color, points in markers.items():
        lines = set()
        for i, (r1, c1) in enumerate(points):
            for r2, c2 in points[i + 1:]:
                if r1 == r2:
                    for c in range(min(c1, c2), max(c1, c2) + 1):
                        lines.add((r1, c))
                elif c1 == c2:
                    for r in range(min(r1, r2), max(r1, r2) + 1):
                        lines.add((r, c1))
        for tile in lines:
            painted.setdefault(tile, set()).add(color)

    for (tr, tc), colors in painted.items():
        value = next(iter(colors)) if len(colors) == 1 else 6
        r0, r1 = row_runs[tr]
        c0, c1 = col_runs[tc]
        for r in range(r0, r1):
            for c in range(c0, c1):
                grid[r][c] = value
    return grid
'''
